ALTER TABLE "tula"."proposals" DROP CONSTRAINT "proposals_status_known";--> statement-breakpoint
ALTER TABLE "tula"."proposals" DROP CONSTRAINT "proposals_approval_whole";--> statement-breakpoint
ALTER TABLE "tula"."proposals" ADD CONSTRAINT "proposals_status_known" CHECK ("tula"."proposals"."status" in ('pending', 'approved', 'rejected', 'executed', 'failed'));--> statement-breakpoint
ALTER TABLE "tula"."proposals" ADD CONSTRAINT "proposals_approval_whole" CHECK (("tula"."proposals"."status" in ('pending', 'rejected')) = ("tula"."proposals"."approved_at" is null) and ("tula"."proposals"."status" in ('pending', 'rejected')) = ("tula"."proposals"."approved_by_type" is null) and ("tula"."proposals"."approved_by_type" is null or "tula"."proposals"."approved_by_type" in ('admin', 'instance_admin')) and ("tula"."proposals"."approved_by_id" is null or ("tula"."proposals"."approved_by_type" is not null and char_length("tula"."proposals"."approved_by_id") between 1 and 128)));